window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-62fc809a5b7c0101"]={"versions": [{"id": "FIG-62fc809a5b7c0101", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram), das einen atomaren Teilschritt der generischen Prüffunktion <code>E2E_PXXCheck()</code> formal spezifiziert.</li>\n<li><strong>Architektur-Kontext:</strong> Bestandteil des AUTOSAR E2E-Protokolls (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, Foundation / Classic & Adaptive Platform). E2E dient der Absicherung sicherheitsrelevanter Inter-ECU- und Intra-ECU-Kommunikation bis ASIL D gemäß ISO 26262 gegen Übertragungsfehler (Verfälschung, Vertauschung, Einfügung).</li>\n<li><strong>Funktionale Einordnung:</strong> Der Teilschritt „Read DataID“ dient der Extraktion der im Nutzdatenstrom explizit übertragenen Identifikationskennung (<code>DataID</code>) aus der empfangenen PDU im Rahmen der Verifikationsroutine eines profilabhängigen E2E-Checkers (<code>XX</code> steht als Platzhalter für Profile mit expliziter DataID-Übertragung, z. B. Profil 04, 05, 06, 07, 22).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität / Funktionskontext:</strong></li>\n<li><code>E2E_PXXCheck()</code>: Normative Prüffunktion der E2E-Bibliothek / des E2E-Transformers für Profil <code>XX</code>.</li>\n<li><strong>Datenstrukturen & Puffer:</strong></li>\n<li><code>Data</code> (IN): Byte-Array (<code>const uint8*</code>) der empfangenen serialisierten Nutzdaten/PDU.</li>\n<li><code>ReceivedDataID</code> (OUT / lokal): Lokale skalare Zielvariable (Typ abhängig von <code>PXXDATAID_LEN</code>, i. d. R. <code>uint16</code> oder <code>uint32</code>), die den extrahierten Identifikator aufnimmt.</li>\n<li><strong>Konfigurationsparameter & Konstanten:</strong></li>\n<li><code>Offset</code>: Basis-Byteoffset innerhalb von <code>Data</code>, an dem der E2E-Header platziert ist (konfiguriert in <code>E2E_PXXConfigType.Offset</code>).</li>\n<li><code>PXXDATAID_POS</code>: Profilspezifische relative Byte-Position der DataID innerhalb des E2E-Headers.</li>\n<li><code>PXXDATAID_LEN</code>: Profilspezifische Länge der DataID in Bytes (z. B. 2 Bytes bei P05, 4 Bytes bei P04/P07).</li>\n<li><strong>Adressierungsbereich:</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{Byte-Range} = [\\text{Offset} + \\text{PXXDATAID\\_POS} \\quad\\dots\\quad \\text{Offset} + \\text{PXXDATAID\\_POS} + \\text{PXXDATAID\\_LEN} - 1]$$</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Eintritt (Initial Node):</strong> Aufruf erfolgt deterministisch und synchron innerhalb des Kontrollflusses von <code>E2E_PXXCheck()</code> nach vorangegangenen Grundprüfungen (z. B. Validierung von Zeigern, Längenprüfung und ggf. „Read Counter“).</li>\n<li><strong>Aktion „Copy DataID from bytestring Data to local variable ReceivedDataID in Big Endian order“:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequentielles Einlesen von <code>PXXDATAID_LEN</code> aufeinanderfolgenden Bytes aus dem Puffer <code>Data</code>, beginnend bei <code>Offset + PXXDATAID_POS</code>.</li>\n<li>Rekonstruktion des Integer-Werts von <code>ReceivedDataID</code> in strikter <strong>Big-Endian-Reihenfolge</strong> (Network Byte Order: das an der niedrigsten Speicheradresse gelesene Byte bildet das Most Significant Byte).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Austritt (Activity Final Node):</strong> Beendigung des Einleseschritts ohne interne Verzweigung. Die extrahierte <code>ReceivedDataID</code> wird unmittelbar an die nachfolgenden Prüfschritte übergeben (Vergleich mit konfigurierter <code>Config-&gt;DataID</code> bzw. Einbindung in die CRC-Kalkulation).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Endianness-Invarianz (Host-Unabhängigkeit):</strong> Unabhängig von der Endianness des Ziel-Controllers (z. B. Little-Endian bei ARM Cortex-M/R, Infineon TriCore/AURIX) schreibt die Spezifikation zwingend Big-Endian-Deserialisierung vor.</li>\n<li><em>Implementierungshinweis:</em> Byteweise Rekonstruktion via Bit-Shifts oder architecturespezifische BSwap-Instruktionen (<code>REV</code>, <code>MOVH</code>) einsetzen, um plattformunabhängige Konformität sicherzustellen:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{ReceivedDataID} = \\sum_{i=0}^{\\text{LEN}-1} \\text{Data}[\\text{Offset} + \\text{POS} + i] \\ll (8 \\cdot (\\text{LEN} - 1 - i))$$</p>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Speichersicherheit (Memory Safety nach ISO 26262):</strong> Vor Ausführung dieser Leseoperation muss die aufrufende Routine zwingend validieren, dass <code>Length &gt;= Offset + PXXDATAID_POS + PXXDATAID_LEN</code>, um Out-of-Bounds-Speicherzugriffe (Memory Violation / Trap) auszuschließen.</li>\n<li><strong>Integrationsort:</strong> Typischerweise implementiert in der AUTOSAR Classic BSW <code>E2E</code> Library bzw. im Adaptive Platform <code>E2E-Transformer</code> (<code>ComXf</code>). Der Schritt blockiert nicht, alloziiert keinen dynamischen Speicher und ist strikt reentrant und deterministisch $O(1)$.</li>\n</ul>"}, {"id": "FIG-69722c1129356118", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram), das einen atomaren Teilschritt der generischen Prüffunktion <code>E2E_PXXCheck()</code> formal spezifiziert.</li>\n<li><strong>Architektur-Kontext:</strong> Bestandteil des AUTOSAR E2E-Protokolls (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, Foundation / Classic & Adaptive Platform). E2E dient der Absicherung sicherheitsrelevanter Inter-ECU- und Intra-ECU-Kommunikation bis ASIL D gemäß ISO 26262 gegen Übertragungsfehler (Verfälschung, Vertauschung, Einfügung).</li>\n<li><strong>Funktionale Einordnung:</strong> Der Teilschritt „Read DataID“ dient der Extraktion der im Nutzdatenstrom explizit übertragenen Identifikationskennung (<code>DataID</code>) aus der empfangenen PDU im Rahmen der Verifikationsroutine eines profilabhängigen E2E-Checkers (<code>XX</code> steht als Platzhalter für Profile mit expliziter DataID-Übertragung, z. B. Profil 04, 05, 06, 07, 22).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität / Funktionskontext:</strong></li>\n<li><code>E2E_PXXCheck()</code>: Normative Prüffunktion der E2E-Bibliothek / des E2E-Transformers für Profil <code>XX</code>.</li>\n<li><strong>Datenstrukturen & Puffer:</strong></li>\n<li><code>Data</code> (IN): Byte-Array (<code>const uint8*</code>) der empfangenen serialisierten Nutzdaten/PDU.</li>\n<li><code>ReceivedDataID</code> (OUT / lokal): Lokale skalare Zielvariable (Typ abhängig von <code>PXXDATAID_LEN</code>, i. d. R. <code>uint16</code> oder <code>uint32</code>), die den extrahierten Identifikator aufnimmt.</li>\n<li><strong>Konfigurationsparameter & Konstanten:</strong></li>\n<li><code>Offset</code>: Basis-Byteoffset innerhalb von <code>Data</code>, an dem der E2E-Header platziert ist (konfiguriert in <code>E2E_PXXConfigType.Offset</code>).</li>\n<li><code>PXXDATAID_POS</code>: Profilspezifische relative Byte-Position der DataID innerhalb des E2E-Headers.</li>\n<li><code>PXXDATAID_LEN</code>: Profilspezifische Länge der DataID in Bytes (z. B. 2 Bytes bei P05, 4 Bytes bei P04/P07).</li>\n<li><strong>Adressierungsbereich:</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{Byte-Range} = [\\text{Offset} + \\text{PXXDATAID\\_POS} \\quad\\dots\\quad \\text{Offset} + \\text{PXXDATAID\\_POS} + \\text{PXXDATAID\\_LEN} - 1]$$</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Eintritt (Initial Node):</strong> Aufruf erfolgt deterministisch und synchron innerhalb des Kontrollflusses von <code>E2E_PXXCheck()</code> nach vorangegangenen Grundprüfungen (z. B. Validierung von Zeigern, Längenprüfung und ggf. „Read Counter“).</li>\n<li><strong>Aktion „Copy DataID from bytestring Data to local variable ReceivedDataID in Big Endian order“:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequentielles Einlesen von <code>PXXDATAID_LEN</code> aufeinanderfolgenden Bytes aus dem Puffer <code>Data</code>, beginnend bei <code>Offset + PXXDATAID_POS</code>.</li>\n<li>Rekonstruktion des Integer-Werts von <code>ReceivedDataID</code> in strikter <strong>Big-Endian-Reihenfolge</strong> (Network Byte Order: das an der niedrigsten Speicheradresse gelesene Byte bildet das Most Significant Byte).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Austritt (Activity Final Node):</strong> Beendigung des Einleseschritts ohne interne Verzweigung. Die extrahierte <code>ReceivedDataID</code> wird unmittelbar an die nachfolgenden Prüfschritte übergeben (Vergleich mit konfigurierter <code>Config-&gt;DataID</code> bzw. Einbindung in die CRC-Kalkulation).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Endianness-Invarianz (Host-Unabhängigkeit):</strong> Unabhängig von der Endianness des Ziel-Controllers (z. B. Little-Endian bei ARM Cortex-M/R, Infineon TriCore/AURIX) schreibt die Spezifikation zwingend Big-Endian-Deserialisierung vor.</li>\n<li><em>Implementierungshinweis:</em> Byteweise Rekonstruktion via Bit-Shifts oder architecturespezifische BSwap-Instruktionen (<code>REV</code>, <code>MOVH</code>) einsetzen, um plattformunabhängige Konformität sicherzustellen:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{ReceivedDataID} = \\sum_{i=0}^{\\text{LEN}-1} \\text{Data}[\\text{Offset} + \\text{POS} + i] \\ll (8 \\cdot (\\text{LEN} - 1 - i))$$</p>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Speichersicherheit (Memory Safety nach ISO 26262):</strong> Vor Ausführung dieser Leseoperation muss die aufrufende Routine zwingend validieren, dass <code>Length &gt;= Offset + PXXDATAID_POS + PXXDATAID_LEN</code>, um Out-of-Bounds-Speicherzugriffe (Memory Violation / Trap) auszuschließen.</li>\n<li><strong>Integrationsort:</strong> Typischerweise implementiert in der AUTOSAR Classic BSW <code>E2E</code> Library bzw. im Adaptive Platform <code>E2E-Transformer</code> (<code>ComXf</code>). Der Schritt blockiert nicht, alloziiert keinen dynamischen Speicher und ist strikt reentrant und deterministisch $O(1)$.</li>\n</ul>"}, {"id": "FIG-bded1c66af5b1b1b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram), das einen atomaren Teilschritt der generischen Prüffunktion <code>E2E_PXXCheck()</code> formal spezifiziert.</li>\n<li><strong>Architektur-Kontext:</strong> Bestandteil des AUTOSAR E2E-Protokolls (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, Foundation / Classic & Adaptive Platform). E2E dient der Absicherung sicherheitsrelevanter Inter-ECU- und Intra-ECU-Kommunikation bis ASIL D gemäß ISO 26262 gegen Übertragungsfehler (Verfälschung, Vertauschung, Einfügung).</li>\n<li><strong>Funktionale Einordnung:</strong> Der Teilschritt „Read DataID“ dient der Extraktion der im Nutzdatenstrom explizit übertragenen Identifikationskennung (<code>DataID</code>) aus der empfangenen PDU im Rahmen der Verifikationsroutine eines profilabhängigen E2E-Checkers (<code>XX</code> steht als Platzhalter für Profile mit expliziter DataID-Übertragung, z. B. Profil 04, 05, 06, 07, 22).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität / Funktionskontext:</strong></li>\n<li><code>E2E_PXXCheck()</code>: Normative Prüffunktion der E2E-Bibliothek / des E2E-Transformers für Profil <code>XX</code>.</li>\n<li><strong>Datenstrukturen & Puffer:</strong></li>\n<li><code>Data</code> (IN): Byte-Array (<code>const uint8*</code>) der empfangenen serialisierten Nutzdaten/PDU.</li>\n<li><code>ReceivedDataID</code> (OUT / lokal): Lokale skalare Zielvariable (Typ abhängig von <code>PXXDATAID_LEN</code>, i. d. R. <code>uint16</code> oder <code>uint32</code>), die den extrahierten Identifikator aufnimmt.</li>\n<li><strong>Konfigurationsparameter & Konstanten:</strong></li>\n<li><code>Offset</code>: Basis-Byteoffset innerhalb von <code>Data</code>, an dem der E2E-Header platziert ist (konfiguriert in <code>E2E_PXXConfigType.Offset</code>).</li>\n<li><code>PXXDATAID_POS</code>: Profilspezifische relative Byte-Position der DataID innerhalb des E2E-Headers.</li>\n<li><code>PXXDATAID_LEN</code>: Profilspezifische Länge der DataID in Bytes (z. B. 2 Bytes bei P05, 4 Bytes bei P04/P07).</li>\n<li><strong>Adressierungsbereich:</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{Byte-Range} = [\\text{Offset} + \\text{PXXDATAID\\_POS} \\quad\\dots\\quad \\text{Offset} + \\text{PXXDATAID\\_POS} + \\text{PXXDATAID\\_LEN} - 1]$$</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Eintritt (Initial Node):</strong> Aufruf erfolgt deterministisch und synchron innerhalb des Kontrollflusses von <code>E2E_PXXCheck()</code> nach vorangegangenen Grundprüfungen (z. B. Validierung von Zeigern, Längenprüfung und ggf. „Read Counter“).</li>\n<li><strong>Aktion „Copy DataID from bytestring Data to local variable ReceivedDataID in Big Endian order“:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Sequentielles Einlesen von <code>PXXDATAID_LEN</code> aufeinanderfolgenden Bytes aus dem Puffer <code>Data</code>, beginnend bei <code>Offset + PXXDATAID_POS</code>.</li>\n<li>Rekonstruktion des Integer-Werts von <code>ReceivedDataID</code> in strikter <strong>Big-Endian-Reihenfolge</strong> (Network Byte Order: das an der niedrigsten Speicheradresse gelesene Byte bildet das Most Significant Byte).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Austritt (Activity Final Node):</strong> Beendigung des Einleseschritts ohne interne Verzweigung. Die extrahierte <code>ReceivedDataID</code> wird unmittelbar an die nachfolgenden Prüfschritte übergeben (Vergleich mit konfigurierter <code>Config-&gt;DataID</code> bzw. Einbindung in die CRC-Kalkulation).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Endianness-Invarianz (Host-Unabhängigkeit):</strong> Unabhängig von der Endianness des Ziel-Controllers (z. B. Little-Endian bei ARM Cortex-M/R, Infineon TriCore/AURIX) schreibt die Spezifikation zwingend Big-Endian-Deserialisierung vor.</li>\n<li><em>Implementierungshinweis:</em> Byteweise Rekonstruktion via Bit-Shifts oder architecturespezifische BSwap-Instruktionen (<code>REV</code>, <code>MOVH</code>) einsetzen, um plattformunabhängige Konformität sicherzustellen:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{ReceivedDataID} = \\sum_{i=0}^{\\text{LEN}-1} \\text{Data}[\\text{Offset} + \\text{POS} + i] \\ll (8 \\cdot (\\text{LEN} - 1 - i))$$</p>\n<ul class=\"fig-list\">\n<li><strong>Puffer- und Speichersicherheit (Memory Safety nach ISO 26262):</strong> Vor Ausführung dieser Leseoperation muss die aufrufende Routine zwingend validieren, dass <code>Length &gt;= Offset + PXXDATAID_POS + PXXDATAID_LEN</code>, um Out-of-Bounds-Speicherzugriffe (Memory Violation / Trap) auszuschließen.</li>\n<li><strong>Integrationsort:</strong> Typischerweise implementiert in der AUTOSAR Classic BSW <code>E2E</code> Library bzw. im Adaptive Platform <code>E2E-Transformer</code> (<code>ComXf</code>). Der Schritt blockiert nicht, alloziiert keinen dynamischen Speicher und ist strikt reentrant und deterministisch $O(1)$.</li>\n</ul>"}], "trans": [{"from": "FIG-62fc809a5b7c0101", "to": "FIG-69722c1129356118", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Aktionsknoten:</strong> Zeilenumbruch der Beschriftung geändert von „Copy DataID from bytestring Data to local variable ReceivedDataID \\n in Big Endian order.“ zu „Copy DataID from bytestring Data to local variable \\n ReceivedDataID in Big Endian order.“.</li>\n<li><strong>Zuschnitt / Bildrand:</strong> Am oberen Rand wurden Reste von umgebendem Fließtext („behave as shown in Figure 6.19...“) abgeschnitten bzw. bereinigt.</li>\n</ul>"}, {"from": "FIG-69722c1129356118", "to": "FIG-bded1c66af5b1b1b", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
